1	<script lang="ts">
2	  import { lang } from '$lib/stores/lang.svelte';
3	  import { i18n, type Lang } from '$lib/i18n';
4	
5	  let currentLang = $state<Lang>('es');
6	  lang.subscribe(v => currentLang = v);
7	
8	  const t = (path: string) => {
9	    let v: any = i18n[currentLang];
10	    for (const k of path.split('.')) { if (v) v = v[k]; else return ''; }
11	    return v || '';
12	  };
13	
14	  interface TooltipState {
15	    text: string;
16	    x: number;
17	    y: number;
18	  }
19	
20	  let tooltip = $state<TooltipState | null>(null);
21	  let hideTimer: ReturnType<typeof setTimeout> | undefined;
22	
23	  function showTooltip(key: string) {
24	    if (hideTimer) clearTimeout(hideTimer);
25	    const desc = i18n[currentLang]?.tech?.[key];
26	    if (!desc) return;
27	
28	    const windowEl = document.querySelector('#design .window__content') as HTMLElement | null;
29	    const grid = document.querySelector('#design .icon-grid') as HTMLElement | null;
30	    if (!windowEl || !grid) return;
31	
32	    const wr = windowEl.getBoundingClientRect();
33	    const gr = grid.getBoundingClientRect();
34	
35	    const tw = 220;
36	    const th = 70;
37	    const pad = 12;
38	
39	    const candidates: Array<{ x: number; y: number }> = [];
40	
41	    for (let i = 0; i < 30; i++) {
42	      const x = wr.left + pad + Math.random() * (wr.width - tw - pad * 2);
43	      const y = wr.top + pad + Math.random() * (wr.height - th - pad * 2);
44	      candidates.push({ x, y });
45	    }
46	
47	    const best = candidates.reduce((a, b) => {
48	      const aOverlap = rectOverlap(a.x, a.y, tw, th, gr.left, gr.top, gr.width, gr.height);
49	      const bOverlap = rectOverlap(b.x, b.y, tw, th, gr.left, gr.top, gr.width, gr.height);
50	      return aOverlap < bOverlap ? a : b;
51	    });
52	
53	    tooltip = { text: desc, x: best.x, y: best.y };
54	    hideTimer = setTimeout(() => tooltip = null, 2500);
55	  }
56	
57	  function rectOverlap(
58	    rx: number, ry: number, rw: number, rh: number,
59	    gx: number, gy: number, gw: number, gh: number
60	  ): number {
61	    const overlapX = Math.max(0, Math.min(rx + rw, gx + gw) - Math.max(rx, gx));
62	    const overlapY = Math.max(0, Math.min(ry + rh, gy + gh) - Math.max(ry, gy));
63	    return overlapX * overlapY;
64	  }
65	
66	  function hideTooltip() {
67	    if (hideTimer) clearTimeout(hideTimer);
68	    tooltip = null;
69	  }
